const MOODS = ['funny','sad','aggressive','dreamy','love','nostalgic','calm','excited','crazy'];


function findSong(query) {
  const q = query.toLowerCase().trim();
  return SONG_LIBRARY.find(s => s.mood === q);
}

// Crossfade-morph two mood pieces into one. First half is mood A,
// second half is mood B (time-scaled to A's length), with a velocity
// crossfade in the 40-60% zone where both pieces overlap and blend.
function morphSongs(songA, songB) {
  if (!songA || !songB) return null;
  const aNotes = songA.notes;
  const bNotes = songB.notes;
  const aMax = Math.max(...aNotes.map(n => n.beat + n.dur));
  const bMax = Math.max(...bNotes.map(n => n.beat + n.dur));
  const bScale = aMax / bMax;
  const fadeStart = aMax * 0.40;
  const fadeEnd   = aMax * 0.60;
  const merged = [];
  for (const n of aNotes) {
    if (n.beat >= fadeEnd) continue;
    let factor = 1;
    if (n.beat > fadeStart) factor = 1 - (n.beat - fadeStart) / (fadeEnd - fadeStart);
    if (factor <= 0.15) continue;
    merged.push({ ...n, _vScale: factor });
  }
  for (const n of bNotes) {
    const scaledBeat = n.beat * bScale;
    if (scaledBeat < fadeStart) continue;
    let factor = 1;
    if (scaledBeat < fadeEnd) factor = (scaledBeat - fadeStart) / (fadeEnd - fadeStart);
    if (factor <= 0.15) continue;
    merged.push({ ...n, beat: scaledBeat, _vScale: factor });
  }
  merged.sort((a, b) => a.beat - b.beat);
  return {
    notes: merged,
    tempo: Math.round((songA.tempo + songB.tempo) / 2),
    title: songA.mood + ' → ' + songB.mood
  };
}

// Reroll: transform a piece with random transposition, octave swaps, and
// rhythmic jitter. Preserves structure & beat positions, varies surface details.
function rerollSong(song) {
  if (!song) return null;
  // Random transpose ±5 semitones, guaranteed nonzero
  let t;
  do { t = Math.floor(Math.random() * 11) - 5; } while (t === 0);
  const newNotes = song.notes.map(n => {
    const midi = name2midi(n.note);
    if (!midi) return n;
    let newMidi = midi + t;
    // 15% chance of octave swap for non-bass notes — adds register variety
    if (midi > 48 && Math.random() < 0.15) {
      newMidi += Math.random() < 0.5 ? -12 : 12;
    }
    while (newMidi < 24) newMidi += 12;
    while (newMidi > 96) newMidi -= 12;
    // Subtle rhythmic jitter
    const durMul = 0.85 + Math.random() * 0.3;
    return {
      note: noteName(newMidi),
      dur: Math.max(0.25, n.dur * durMul),
      beat: n.beat
    };
  });
  return {
    notes: newNotes,
    tempo: Math.max(50, song.tempo + (Math.floor(Math.random() * 21) - 10)),
    title: song.title
  };
}

